import { expect, it } from 'vitest'
import { render, screen, fireEvent } from '@testing-library/react'
import { App } from './App'

it('keeps exactly the selected view highlighted across switches and later renders', async () => {
  render(<App />)
  const list = screen.getByRole('button', { name: 'List' })
  const preview = screen.getByRole('button', { name: 'Preview' })
  for (const selected of [list, preview, list, preview]) {
    fireEvent.click(selected)
    await new Promise(resolve => setTimeout(resolve, 80))
    expect(selected.classList.contains('is-active')).toBe(true)
    expect(selected.getAttribute('aria-pressed')).toBe('true')
    expect((selected === list ? preview : list).classList.contains('is-active')).toBe(false)
  }
})
EOF
